        var h = hs[i], m = h.object.material; if (Array.isArray(m)) m = m[0];
        if (!h.object.isMesh || (m && m.transparent && m.opacity < 0.6)) continue;
        var vis = true; for (var ob = h.object; ob; ob = ob.parent) if (!ob.visible) { vis = false; break; }
        if (vis) { best = h.distance; break; }
